import { HttpBackend, HttpClient } from '@angular/common/http';
import { Injectable, NgZone } from '@angular/core';
import * as _ from 'lodash';
import { of, Subject } from 'rxjs';
import { catchError } from 'rxjs/operators';


export type VersionParameter = string | number | undefined;

export interface IEventConfig {
  minVersion?: VersionParameter; // Used (with maxVersion) to support multiple versions of a deployed application with the same config, and ensure we only track what we want, when we want it, and in which versions of the application.
  maxVersion?: VersionParameter;
  events: DynamicEvent[];
}

export interface IEventConfigDefinition {
  configs: IEventConfig[];
}

export type DynamicEvent =
  IDynamicEventWithEventAction |
  IDynamicEventWithSelector |
  ITimedEvent |
  IMouseEvent |
  IKeyboardEvent |
  IBeforeUnloadEvent |
  ISequence;

export enum DynamicType {
  Simple, // Standalone events. Trackable.
  Sequence, // Complex events. Trigger multiple "StepEvents" first to trigger a "Sequence". Sequences may also be used to trigger other sequences. Trackable (optional).
  StepEvent, // Similar to a "Simple" event but used as one step of a "Sequence". May optionally fire an analytics event when triggered. Not trackable.
}

export enum MiscellaneousEventAction {
  Beforeunload = 'beforeunload', // Can be used to finalize a sequence. e.g. "Fire an event when the user begins to create some new data, but closes the browser without saving their changes". Trackable.
  Timed = 'timed' // Must only be used in a sequence, either to progress the sequence after some time, or to trigger a sequence cancellation event. Not trackable.
}

export enum MouseEventAction {
  Click = 'click',
  MouseOver = 'mouseover',
  MouseOut = 'mouseout',
  MouseDown = 'mousedown',
  MouseUp = 'mouseup',
}

export enum KeyboardEventAction {
  KeyPress = 'keypress',
  KeyDown = 'keydown',
  KeyUp = 'keyup',
}

export type EventAction =
  MiscellaneousEventAction |
  MouseEventAction |
  KeyboardEventAction;

interface IDynamicEventBase {
  id: number;
  dynamicType: DynamicType;
  label?: string;
  message: string;
  additionalDataSelectors?: string[]; // Optional. Used to fetch additional data from the DOM. Will attempt to grab an input value if possible.
  additionalData?: (string | undefined)[]; // Do not include with event config. This will be filled in when the event fires, if the additionalDataSelector is defined and evaluates to anything.
  [key: string]: any; // Allow any arbitrary data to be included with the event config
}

export interface IDynamicEventWithEventAction extends IDynamicEventBase {
  eventAction: EventAction;
}

export interface IDynamicEventWithSelector extends IDynamicEventWithEventAction {
  selector: string; // DOM/CSS selector used to trigger the event
  statusSelector?: string; // Optional. Used to determine, at event time, whether the event is valid. e.g. "Fire event X by clicking on button Y, but only if element Z is visible and enabled"
}

export interface ISimpleEvent extends IDynamicEventWithSelector {
  dynamicType: DynamicType.Simple;
}

export interface IStepEvent extends IDynamicEventWithSelector {
  dynamicType: DynamicType.StepEvent;
  additionalDataSelectors: undefined; // Step events are not tracked.
}

export interface ITimedEvent extends IDynamicEventWithEventAction {
  dynamicType: DynamicType.StepEvent | DynamicType.Simple;
  eventAction: MiscellaneousEventAction.Timed;
  selector: undefined;
  timeout: number;
}

export interface IMouseEvent extends IDynamicEventWithEventAction {
  dynamicType: DynamicType.StepEvent | DynamicType.Simple;
  eventAction: MouseEventAction;
  selector: string;
}

export interface IKeyboardEvent extends IDynamicEventWithEventAction {
  dynamicType: DynamicType.StepEvent | DynamicType.Simple;
  eventAction: KeyboardEventAction;
  selector: string;
  isAlphaNumeric: boolean;
}

export interface IBeforeUnloadEvent extends IDynamicEventWithEventAction {
  dynamicType: DynamicType.StepEvent | DynamicType.Simple;
  eventAction: MiscellaneousEventAction.Beforeunload;
  selector: string;
}

export interface ISequence extends IDynamicEventBase {
  dynamicType: DynamicType.Sequence;
  steps: number[]; // Ids corresponding to events that continue a sequence.
  cancelledBy: number[]; // Ids corresponding to events that will trigger the cancellation of a sequence.
  isTrackable: boolean; // Sequences are intended to chain together other events or sequences. Whether the completion of a sequence itself isTrackable or not is optional. If this is set to false, the sequence should contain at least 1 simple event or chain with another, trackable sequence.
  timeout?: number; // Timeout in milliseconds. If a step event is not triggered within this time, the sequence will be cancelled.
}

@Injectable({providedIn: 'root'})
export class DynamicAnalyticsService {
  readonly onEvent = new Subject<DynamicEvent>();

  loggingEnabled = false;

  private httpClient: HttpClient;
  private versionFilterPredicate!: (minVersion: VersionParameter, maxVersion: VersionParameter) => boolean;

  private filteredEvents: DynamicEvent[] = [];
  private sequences: ISequence[] = [];

  // Delegation state
  private delegatedHandlers = new Map<string, (event: Event) => void>();
  private beforeUnloadHandler?: (event: Event) => void;
  private isInitialized = false;

  // Sequence state
  private readonly sequenceTracker: Record<number, number[]> = {};
  private readonly timedEventForSequenceTracker: Record<number, Record<number, any>> = {};
  private readonly blockedSequenceIds: number[] = [];

  // Precomputed lookup maps for faster event dispatch (avoid filtering arrays on every DOM event)
  private delegatedConfigsByEventAction = new Map<EventAction, IDynamicEventWithSelector[]>();
  private documentConfigsByEventAction = new Map<EventAction, IDynamicEventWithSelector[]>();
  private beforeUnloadConfigs: IDynamicEventWithEventAction[] = [];
  private configsNeedingStatusSelectorCheck = new Map<number, string>();

  constructor(httpBackend: HttpBackend, private zone: NgZone) {
    this.httpClient = new HttpClient(httpBackend);

    /*
Test cases:
- Click events / Simple event

- Click X, then Y event / Sequence
- Mouse-over, then mouse-out without clicking inside event / Sequence with cancel event
- Click X (to open), then click Y to close without clicking Z events / Sequence with cancel event

- Count number of times event X has been fired this session?

- Window closed event. Use to submit values gathered using sequences, or event totals during a session. "How many times did sequence/event X happen in the session"
- Hourly/Minutely events to send totals during the last hour/minute
-
- Get a specific value from the DOM when firing an event (run arbitrary JS? Or just inspect DOM info?)
*/

    // this.eventConfigDefinition = {
    //   configs: [
    //     {
    //       minVersion: '',
    //       maxVersion: '',
    //       events: [
    //         // Simple click event
    //         {id: 1, dynamicType: DynamicType.StepEvent, selector: '.toolbar-container > button', eventType: EventType.Click, message: 'Click ellipsis menu'},
    //         {id: 2, dynamicType: DynamicType.StepEvent, selector: '.mat-mdc-menu-content button:nth-child(1)', eventType: EventType.Click, message: 'Click New Operation'},
    //         {id: 3, dynamicType: DynamicType.StepEvent, selector: '.mat-mdc-menu-content button:nth-child(2)', eventType: EventType.Click, message: 'Click Location Wizard'},
    //         {id: 4, dynamicType: DynamicType.StepEvent, selector: '.cdk-overlay-backdrop', eventType: EventType.Click, message: 'Click anywhere (other than sequence element(s))'},
    //         // {id: 4, dynamicType: DynamicType.StepEvent, selector: 'document', eventType: EventType.Click, message: 'Click anywhere (other than sequence element(s))'},
    //         {id: 5, dynamicType: DynamicType.Sequence, message: 'Click rating points icon', stepEvents: [1, 3], cancelEvents: [2, 4], isTrackable: true},
    //       ]
    //     }
    //   ]
    // };
    // this.log(JSON.stringify(this.eventConfigDefinition));
  }

  initialize(
    url: string,
    versionFilterPredicate: (minVersion: VersionParameter, maxVersion: VersionParameter) => boolean
  ) {
    this.versionFilterPredicate = versionFilterPredicate;
    this.initializeAnalyticsConfiguration(url);
  }

  initializeWithConfig(
    eventConfigDefinition: IEventConfigDefinition,
    versionFilterPredicate: (minVersion: VersionParameter, maxVersion: VersionParameter) => boolean
  ) {
    this.versionFilterPredicate = versionFilterPredicate;
    this.initializeEventConfigDefinition(eventConfigDefinition);
  }

  /**
   * Optional cleanup if you ever need to tear down (e.g. hot reload / tests).
   */
  destroy() {
    this.zone.runOutsideAngular(() => {
      for (const [eventName, handler] of this.delegatedHandlers.entries()) {
        document.removeEventListener(eventName, handler, true);
      }
      this.delegatedHandlers.clear();

      if (!_.isNil(this.beforeUnloadHandler)) {
        window.removeEventListener('beforeunload', this.beforeUnloadHandler);
        this.beforeUnloadHandler = undefined;
      }
    });

    this.isInitialized = false;

    this.filteredEvents = [];
    this.sequences = [];

    this.delegatedConfigsByEventAction.clear();
    this.documentConfigsByEventAction.clear();
    this.configsNeedingStatusSelectorCheck.clear();
    this.beforeUnloadConfigs = [];

    // Reset per-session tracking
    this.clearAllSequenceState();
  }

  private initializeAnalyticsConfiguration(url: string) {
    this.getConfiguration$(url).subscribe(eventConfigDefinition => this.initializeEventConfigDefinition(eventConfigDefinition));
  }

  private initializeEventConfigDefinition(eventConfigDefinition: IEventConfigDefinition | undefined) {
    if (_.isEmpty(eventConfigDefinition?.configs)) {
      console.warn('No analytics configuration found');
      return;
    }

    const filteredEventConfigs = _.filter(
      eventConfigDefinition!.configs,
      config => this.versionFilterPredicate(config.minVersion, config.maxVersion)
    );

    this.validateEventConfigDefinition(filteredEventConfigs);

    const events: DynamicEvent[] = [];
    _.each(eventConfigDefinition!.configs, config => {
      if (this.versionFilterPredicate(config.minVersion, config.maxVersion)) {
        events.push(...config.events);
      }
    });

    this.filteredEvents = events;

    if (_.isEmpty(this.filteredEvents)) {
      console.warn('No analytics events found for this application version');
      return;
    }

    this.sequences = _.filter(this.filteredEvents, dynamicEvent => this.isSequence(dynamicEvent));

    this.precomputeListenerConfiguration();

    this.installDelegatedListeners();
    this.installBeforeUnloadListener();

    this.isInitialized = true;
  }

  private precomputeListenerConfiguration() {
    this.delegatedConfigsByEventAction.clear();
    this.documentConfigsByEventAction.clear();
    this.configsNeedingStatusSelectorCheck.clear();

    // Precompute statusSelector presence so we don't branch or re-check string emptiness repeatedly.
    _.each(this.filteredEvents, dynamicEvent => {
      if (this.isDynamicEventWithSelector(dynamicEvent)) {
        const selectorEvent = dynamicEvent as IDynamicEventWithSelector;

        if (!_.isNil(selectorEvent.statusSelector) && !_.isEmpty(selectorEvent.statusSelector)) {
          this.configsNeedingStatusSelectorCheck.set(selectorEvent.id, selectorEvent.statusSelector);
        }

        if (selectorEvent.selector === 'document') {
          const existingDocumentConfigs = this.documentConfigsByEventAction.get(selectorEvent.eventAction) ?? [];
          existingDocumentConfigs.push(selectorEvent);
          this.documentConfigsByEventAction.set(selectorEvent.eventAction, existingDocumentConfigs);
        } else {
          const existingDelegatedConfigs = this.delegatedConfigsByEventAction.get(selectorEvent.eventAction) ?? [];
          existingDelegatedConfigs.push(selectorEvent);
          this.delegatedConfigsByEventAction.set(selectorEvent.eventAction, existingDelegatedConfigs);
        }
      }
    });

    // Cache beforeunload configs once (avoid filtering each time).
    this.beforeUnloadConfigs = this.filteredEvents.filter(dynamicEvent => this.isBeforeUnloadEventType(dynamicEvent)) as IDynamicEventWithEventAction[];
  }

  private installDelegatedListeners() {
    const requiredEventActions = new Set<string>();

    for (const eventAction of this.delegatedConfigsByEventAction.keys()) {
      requiredEventActions.add(String(eventAction));
    }
    for (const eventAction of this.documentConfigsByEventAction.keys()) {
      requiredEventActions.add(String(eventAction));
    }

    // Install one capturing handler per event type.
    this.zone.runOutsideAngular(() => {
      requiredEventActions.forEach(eventActionName => {
        if (this.delegatedHandlers.has(eventActionName)) {
          return;
        }

        const handler = (event: Event) => {
          this.handleDelegatedEvent(eventActionName as EventAction, event);
        };

        this.delegatedHandlers.set(eventActionName, handler);

        // Capture helps when components stopPropagation in bubble phase.
        document.addEventListener(eventActionName, handler, true);
      });
    });
  }

  private installBeforeUnloadListener() {
    if (_.isEmpty(this.beforeUnloadConfigs)) {
      return;
    }

    this.beforeUnloadHandler = () => {
      this.onBeforeUnload();
    };

    this.zone.runOutsideAngular(() => {
      window.addEventListener('beforeunload', this.beforeUnloadHandler!);
    });
  }

  private handleDelegatedEvent(eventAction: EventAction, event: Event) {
    if (!this.isInitialized) {
      return;
    }

    // 1) Handle "document" selector configs first.
    //    These are defined as selector === 'document' and should fire regardless of target.
    const documentConfigsForAction = this.documentConfigsByEventAction.get(eventAction) ?? [];
    for (const documentConfig of documentConfigsForAction) {
      this.getOnDynamicEventHandler(documentConfig)(event);
    }

    // 2) Handle element selector configs via delegation.
    const delegatedConfigsForAction = this.delegatedConfigsByEventAction.get(eventAction) ?? [];
    if (_.isEmpty(delegatedConfigsForAction)) {
      return;
    }

    const targetElement = event.target as Element | null;
    if (_.isNil(targetElement)) {
      return;
    }

    for (const delegatedConfig of delegatedConfigsForAction) {
      const matchingElement = this.closestMatching(targetElement, delegatedConfig.selector);
      if (_.isNil(matchingElement)) {
        continue;
      }

      const isValidForStatusSelector = this.isValidForStatusSelector(delegatedConfig);
      if (!isValidForStatusSelector) {
        continue;
      }

      // Fire the configured analytics event, using the matched element as the "element context".
      // We pass match to keep your "element still matches selector" guard meaningful.
      this.getOnDynamicEventHandler(delegatedConfig, matchingElement)(event);
    }
  }

  private isValidForStatusSelector(dynamicEvent: IDynamicEventWithSelector): boolean {
    const statusSelector = this.configsNeedingStatusSelectorCheck.get(dynamicEvent.id);
    if (_.isNil(statusSelector)) {
      return true;
    }

    const matchingStatusElements = document.querySelectorAll(statusSelector);
    if (_.isNil(matchingStatusElements) || matchingStatusElements.length === 0) {
      return false;
    }

    return true;
  }

  private closestMatching(start: Element, selector: string): Element | null {
    // Some selectors may be invalid; guard so one bad selector doesn't break everything.
    try {
      return start.closest(selector);
    } catch (error) {
      console.error('Invalid selector in dynamic analytics config:', selector, error);
      return null;
    }
  }

  private getConfiguration$(url: string) {
    return this.httpClient
      .get<IEventConfigDefinition>(url)
      .pipe(
        catchError(error => {
          console.error('Unable to retrieve dynamic analytics configuration');
          console.error(error);
          return of(undefined);
        })
      );
  }

  private getOnDynamicEventHandler(
    dynamicEvent: IDynamicEventWithEventAction,
    element?: Element
  ): (event?: Event) => void {
    return (event?: Event) => {
      // Only enforce "still matches" if we have element context and selector event.
      if (!_.isNil(element) && this.isDynamicEventWithSelector(dynamicEvent)) {
        const selectorToCheck = dynamicEvent.statusSelector ?? dynamicEvent.selector;
        const elementsMatchingSelector = document.querySelectorAll(selectorToCheck);

        const doesElementMatchConfig = this.doesElementMatchConfig(dynamicEvent, element, elementsMatchingSelector);
        if (!doesElementMatchConfig) {
          this.log(`Element no longer matches selector. Cancelling event ${dynamicEvent.id}`);
          return;
        }
      }

      this.onSimpleOrStepEvent(dynamicEvent, event);
    };
  }

  private doesElementMatchConfig(
    dynamicEvent: IDynamicEventWithSelector,
    element: Element,
    elementsMatchingSelector: NodeListOf<Element>
  ): boolean {
    if (_.isNil(dynamicEvent.statusSelector)) {
      return _.some(elementsMatchingSelector, matchingElement => matchingElement === element);
    }

    return elementsMatchingSelector.length > 0;
  }

  private onSimpleOrStepEvent(dynamicEvent: IDynamicEventWithEventAction | ISimpleEvent | IStepEvent, event?: Event) {
    const isSimpleEvent = this.isSimpleEvent(dynamicEvent);

    if (isSimpleEvent) {
      const shouldTrackKeyboardEvent = this.shouldTrackKeyboardEvent(dynamicEvent, event);
      if (shouldTrackKeyboardEvent) {
        const additionalData = this.getAdditionalEventData(dynamicEvent);
        this.trackEvent(dynamicEvent, additionalData);
      }
    }

    if (isSimpleEvent || this.isStepEvent(dynamicEvent)) {
      this.onStepEvent(dynamicEvent, event);
    }
  }

  private shouldTrackKeyboardEvent(dynamicEvent: IDynamicEventWithEventAction | ISimpleEvent | IStepEvent, event?: Event): boolean {
    if (_.isNil(event)) {
      return true;
    }

    if (!this.isKeyboardEventType(dynamicEvent)) {
      return true;
    }

    const keyboardDynamicEvent = dynamicEvent as IKeyboardEvent;
    if (!keyboardDynamicEvent.isAlphaNumeric) {
      return true;
    }

    return this.isAlphaNumericKeyboardEvent(event);
  }

  private onBeforeUnload() {
    if (_.isEmpty(this.beforeUnloadConfigs)) {
      return;
    }

    for (const beforeUnloadConfig of this.beforeUnloadConfigs) {
      this.getOnDynamicEventHandler(beforeUnloadConfig)();
    }
  }

  private trackEvent(event: DynamicEvent, additionalData: (string | undefined)[] | undefined) {
    this.logEvent(event);

    // Re-enter Angular only when notifying subscribers.
    this.zone.run(() => {
      this.onEvent.next({
        ...event,
        additionalData
      });
    });
  }

  private getAdditionalEventData(dynamicEvent: IDynamicEventBase): (string | undefined)[] | undefined {
    let additionalData: (string | undefined)[] | undefined;

    if (!_.isEmpty(dynamicEvent.additionalDataSelectors)) {
      additionalData = dynamicEvent.additionalDataSelectors!.map(selector => {
        const elementWithData = document.querySelector(selector);
        if (!_.isNil(elementWithData)) {
          if (elementWithData instanceof HTMLInputElement) {
            return elementWithData.value;
          }
          return (elementWithData as HTMLElement).innerHTML;
        }
        return undefined;
      });
    }

    return additionalData;
  }

  private isAlphaNumericKeyboardEvent(event: Event): boolean {
    return ((event as unknown as KeyboardEvent)?.key?.length ?? 0) === 1;
  }

  private log(text: string) {
    if (this.loggingEnabled) {
      console.log(text)
    }
  }

  private formatDynamicEventString(event: DynamicEvent): string {
    const isSimpleEvent = this.isSimpleEvent(event);

    if (isSimpleEvent || this.isStepEvent(event)) {
      let logDetails = `${event.id}. ${event.message}`;
      if (!_.isNil(event.selector)) {
        logDetails += `. ${event.selector}`;
      }
      if (isSimpleEvent) {
        return `** Tracking simple event: ${logDetails}`;
      } else if (this.isStepEvent(event)) {
        return `Step event: ${logDetails} ${this.getSequenceProgress(event)}`;
      }
    }

    return `** Tracking sequence: ${event.id}. ${event.message}`;
  }

  private getSequenceProgress(dynamicEvent: IStepEvent | ISequence): string {
    const sequencesContainingThisEvent = _.filter(this.sequences, sequence => _.includes(sequence.steps, dynamicEvent.id));
    const progress: string[] = [];

    _.each(sequencesContainingThisEvent, sequence => {
      if (_.includes(this.sequenceTracker[sequence.id], dynamicEvent.id)) {
        progress.push(`Sequence ${sequence.id} = ${this.sequenceTracker[sequence.id].length}/${sequence.steps.length}`);
      }
    });

    return progress.join(', ');
  }

  private onStepEvent(dynamicEvent: ISimpleEvent | IStepEvent | ISequence, event?: Event) {
    const sequencesCancelledByThisEvent = _.filter(this.sequences, sequence => _.includes(sequence.cancelledBy, dynamicEvent.id));

    if (!_.isEmpty(sequencesCancelledByThisEvent)) {
      const resetSequences: ISequence[] = [];

      _.each(sequencesCancelledByThisEvent, sequence => {
        const tracker = (this.sequenceTracker[sequence.id] = this.sequenceTracker[sequence.id] ?? []);
        if (!_.isEmpty(tracker) &&
          _.includes(sequence.cancelledBy, dynamicEvent.id) &&
          !this.doesEventTargetTriggerStepEvent(sequence, event)) {

          resetSequences.push(sequence);
          this.resetSequence(sequence);
          this.blockedSequenceIds.push(sequence.id);

          setTimeout(() => {
            _.pull(this.blockedSequenceIds, sequence.id);
          }, 10);
        }
      });

      if (!_.isEmpty(resetSequences)) {
        this.log(`Sequence reset by event ${dynamicEvent.id}: ${resetSequences.map(sequence => sequence.id).join(',')}`);
      }
    }

    const sequencesContainingThisEvent = _.filter(
      this.sequences,
      sequence =>
        _.includes(sequence.steps, dynamicEvent.id) &&
        !_.includes(this.blockedSequenceIds, sequence.id)
    );

    _.each(sequencesContainingThisEvent, sequence => {
      setTimeout(() => {
        _.pull(this.blockedSequenceIds, sequence.id);
      }, 10);

      const tracker = this.sequenceTracker[sequence.id] = this.sequenceTracker[sequence.id] ?? [];

      if (sequence.steps[tracker.length] === dynamicEvent.id) {
        this.log(`Adding event ${dynamicEvent.id} to Sequence ${sequence.id} tracker`);
        tracker.push(dynamicEvent.id);
        this.blockedSequenceIds.push(sequence.id);
        // this.logEvent(dynamicEvent); // TODO: Fix: Logging a misleading tracking sequence when a trackable event leads into another sequence
      }

      if (tracker.length === sequence.steps.length) {
        this.log(`Sequence ${sequence.id} complete`);
        this.trackAndResetSequence(sequence);
        this.onStepEvent(sequence);
      } else {
        const nextEventIdInSequence = sequence.steps[tracker.length];
        const nextEventInSequence = _.find(this.filteredEvents, {id: nextEventIdInSequence});

        if (_.isNil(nextEventInSequence)) {
          throw new Error(`Error: Next event in sequence not found. Incorrect Id specified? Next event id ${nextEventIdInSequence}. Sequence ${sequence.id}`);
        }

        if (this.isTimedEvent(nextEventInSequence)) {
          this.startTimedEventTimerForSequence(nextEventInSequence, sequence);
        }

        if (tracker.length === 1 && !_.isNil(sequence.timeout)) {
          this.startSequenceTimeout(sequence);
        }
      }
    });
  }

  private startTimedEventTimerForSequence(dynamicEvent: ITimedEvent, sequence: ISequence) {
    const timer = dynamicEvent.timeout;
    if (timer <= 0) {
      throw new Error(`Timeout value must be greater than 0 for event ${dynamicEvent.id}`);
    }

    const tracker = (this.timedEventForSequenceTracker[sequence.id] = this.timedEventForSequenceTracker[sequence.id] ?? {});

    if (!_.isNil(tracker[dynamicEvent.id])) {
      throw new Error(`Timer event already exists for event ${dynamicEvent.id} in sequence ${sequence.id}`);
    }

    this.log(`Timer starting for event ${dynamicEvent.id} in sequence ${sequence.id}`);

    tracker[dynamicEvent.id] = setTimeout(() => {
      delete tracker[dynamicEvent.id];
      this.log(`Timer complete for event ${dynamicEvent.id} in sequence ${sequence.id}`);
      this.onSimpleOrStepEvent(dynamicEvent);
    }, timer);
  }

  private resetTimersForSequence(sequence: ISequence) {
    const tracker = this.timedEventForSequenceTracker[sequence.id];
    if (!_.isNil(tracker)) {
      _.each(tracker, timeoutId => clearTimeout(timeoutId));
    }
    delete this.timedEventForSequenceTracker[sequence.id];
  }

  private startSequenceTimeout(sequence: ISequence) {
    const tracker = this.timedEventForSequenceTracker[sequence.id] = this.timedEventForSequenceTracker[sequence.id] ?? {};
    tracker[sequence.id] = setTimeout(() => {
      if (!_.isEmpty(this.sequenceTracker[sequence.id])) {
        this.log(`Sequence ${sequence.id} timed out`);
        this.resetSequence(sequence);
      }
    }, sequence.timeout);
  }

  private resetSequence(sequence: ISequence) {
    this.sequenceTracker[sequence.id] = [];
    this.resetTimersForSequence(sequence);
    this.log(`Cancelling sequence: ${sequence.id}. Message: ${sequence.message}`);
  }

  private trackAndResetSequence(sequence: ISequence) {
    this.resetSequence(sequence);
    if (sequence.isTrackable) {
      const additionalData = this.getAdditionalEventData(sequence);
      this.trackEvent(sequence, additionalData);
    }
  }

  private logEvent(event: DynamicEvent) {
    if (this.isSequence(event) && !event.isTrackable) {
      return;
    }
    this.log(this.formatDynamicEventString(event));
  }

  // Type guards
  private isStepEvent(event: DynamicEvent): event is IStepEvent {
    return event.dynamicType === DynamicType.StepEvent;
  }

  private isSimpleEvent(event: DynamicEvent): event is ISimpleEvent {
    return event.dynamicType === DynamicType.Simple;
  }

  private isBeforeUnloadEventType(event: DynamicEvent): event is IBeforeUnloadEvent {
    return (this.isSimpleEvent(event) || this.isStepEvent(event)) && (event).eventAction === MiscellaneousEventAction.Beforeunload;
  }

  private isKeyboardEventType(event: DynamicEvent): event is IKeyboardEvent {
    return (this.isSimpleEvent(event) || this.isStepEvent(event)) && (event).eventAction in KeyboardEventAction;
  }

  private isDynamicEventWithSelector(event: DynamicEvent): event is IDynamicEventWithSelector {
    return (this.isSimpleEvent(event) || this.isStepEvent(event)) && (event).selector !== undefined;
  }

  private isSequence(event: DynamicEvent): event is ISequence {
    return event.dynamicType === DynamicType.Sequence;
  }

  private isTimedEvent(event: DynamicEvent): event is ITimedEvent {
    return (this.isSimpleEvent(event) || this.isStepEvent(event)) && (event).eventAction === MiscellaneousEventAction.Timed;
  }

  private doesEventTargetTriggerStepEvent(sequence: ISequence, event?: Event) {
    if (_.isNil(event)) {
      return false;
    }

    const tracker = this.sequenceTracker[sequence.id];
    if (_.isEmpty(tracker)) {
      return false;
    }

    const otherStepEventId = sequence.steps[tracker.length - 1];
    const stepEvent = _.find(this.filteredEvents, dynamicEvent => dynamicEvent.id === otherStepEventId);

    if (_.isNil(stepEvent) || !this.isDynamicEventWithSelector(stepEvent)) {
      return false;
    }

    const elementsMatchingSelector = document.querySelectorAll(stepEvent.statusSelector ?? stepEvent.selector);
    const target = event.target as Node;

    return _.some(elementsMatchingSelector, element => element === target || element.contains(target));
  }

  private validateEventConfigDefinition(filteredEventConfigs: IEventConfig[]) {
    const uniqueEventIds = new Set<number>();
    const uniqueSequenceStepEventIds = new Set<number>();
    const uniqueCancelEventIds = new Set<number>();

    _.each(filteredEventConfigs, config => {
      _.each(config.events, event => {
        if (uniqueEventIds.has(event.id)) {
          throw new Error('Event ids must be unique');
        }
        uniqueEventIds.add(event.id);

        if (this.isSequence(event)) {
          if (event.steps.length < 2) {
            throw new Error('Sequences must have at least 2 event ids');
          }

          event.steps.forEach(id => {
            if (id === event.id) {
              throw new Error('Sequences cannot reference their own id as a step event');
            }
            uniqueSequenceStepEventIds.add(id);
          });

          event.cancelledBy.forEach(id => {
            if (id === event.id) {
              throw new Error('Sequences cannot reference their own id as a cancel event');
            }
            uniqueCancelEventIds.add(id);
          });
        }

        if (this.isTimedEvent(event) && (event.timeout <= 0 || _.isNaN(event.timeout))) {
          throw new Error('Timeout event must be a number greater than zero');
        }

        if (!_.isNil(event.additionalData)) {
          throw new Error('Additional data must not be provided in the configuration. Use `additionalDataSelectors` to allow the service to find additional data in the DOM at event-time');
        }

        if (!_.isNil(event.additionalDataSelectors) && _.some(event.additionalDataSelectors, (selector: string) => _.isEmpty(selector))) {
          throw new Error('Additional data selectors cannot be an empty string');
        }

        if (this.isDynamicEventWithSelector(event) && !_.isNil(event.selector) && _.isEmpty(event.selector)) {
          throw new Error('Selector cannot be an empty string');
        }
      });
    });

    uniqueSequenceStepEventIds.forEach(id => {
      if (!uniqueEventIds.has(id)) {
        throw new Error('Step events must exist');
      }
    });

    uniqueCancelEventIds.forEach(id => {
      if (!uniqueEventIds.has(id)) {
        throw new Error('Cancel events must exist');
      }
    });
  }

  private clearAllSequenceState() {
    for (const sequenceIdKey of Object.keys(this.sequenceTracker)) {
      delete this.sequenceTracker[Number(sequenceIdKey)];
    }

    for (const sequenceTimerKey of Object.keys(this.timedEventForSequenceTracker)) {
      delete this.timedEventForSequenceTracker[Number(sequenceTimerKey)];
    }

    this.blockedSequenceIds.length = 0;
  }
}
